use std::fs

fn eval(line: string) -> string {
    let mut stack: Vec<int> = []
    for tok in line.split(" ") {
        if tok == "" {
            continue
        }
        if tok == "+" || tok == "-" || tok == "*" || tok == "/" {
            let n = stack.len()
            if n < 2 {
                return "error: underflow"
            }
            let b = stack[n - 1]
            let a = stack[n - 2]
            stack.truncate(n - 2)
            if tok == "+" {
                stack.push(a + b)
            } else if tok == "-" {
                stack.push(a - b)
            } else if tok == "*" {
                stack.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                stack.push(a / b)
            }
        } else {
            match tok.parse::<int>() {
                Ok(v) => {
                    if tok.starts_with("+") {
                        return "error: token"
                    }
                    stack.push(v)
                }
                Err(_) => {
                    return "error: token"
                }
            }
        }
    }
    if stack.len() != 1 {
        return "error: leftover"
    }
    "${stack[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" {
            continue
        }
        println(eval(line))
    }
}

